const onboardingSteps=()=>[
{icon:'⌖',title:tr('Bienvenue sur LUXE RADAR','Welcome to LUXE RADAR'),copy:tr('Trouve des annonces pertinentes sur plusieurs marketplaces, sans te perdre dans des centaines de menus.','Find relevant listings across several marketplaces without getting lost in hundreds of menus.'),benefits:[tr('Une recherche simple','One simple search'),tr('Les meilleurs résultats en premier','Best results first'),tr('La suite chargée automatiquement','More loaded automatically')]},
{icon:'♡',title:tr('Garde seulement l’essentiel','Keep only what matters'),copy:tr('Ajoute les bonnes annonces aux favoris et crée une alerte pour reprendre ta recherche plus tard.','Save the right listings and create an alert so you can return to your search later.'),benefits:[tr('Favoris privés','Private favorites'),tr('Alertes relançables','Reusable alerts'),tr('Historique automatique','Automatic history')]},
{icon:'✓',title:tr('Tu es prêt','You are ready'),copy:tr('L’interface démarre en mode Essentiel. Passe au mode Expert uniquement quand tu veux accéder aux outils de revente.','The interface starts in Essential mode. Switch to Expert only when you want access to reseller tools.'),benefits:[tr('Aucun réglage obligatoire','No required setup'),tr('Mode clair ou sombre','Light or dark mode'),tr('Données conservées sur cet appareil','Data kept on this device')]}
];let onboardingIndex=0;
function showOnboarding(index=0){onboardingIndex=index;const steps=onboardingSteps(),step=steps[index],root=$('#onboarding-content');root.replaceChildren();const visual=document.createElement('div');visual.className='onboarding-visual';visual.textContent=step.icon;const title=document.createElement('h2');title.textContent=step.title;const copy=document.createElement('p');copy.textContent=step.copy;const list=document.createElement('div');list.className='benefit-list';step.benefits.forEach(text=>{const row=document.createElement('div');row.className='benefit-item';const check=document.createElement('b');check.textContent='✓';const span=document.createElement('span');span.textContent=text;row.append(check,span);list.append(row)});root.append(visual,title,copy,list);$$('.onboarding-progress span').forEach((dot,i)=>dot.classList.toggle('active',i<=index));$('#onboarding-next').textContent=index===steps.length-1?tr('Commencer','Start'):tr('Continuer','Continue');$('#onboarding').hidden=false}
function finishOnboarding(){store.set('onboardingComplete',true);$('#onboarding').hidden=true;navigate('radar')}
$('#onboarding-next')?.addEventListener('click',()=>onboardingIndex<onboardingSteps().length-1?showOnboarding(onboardingIndex+1):finishOnboarding());
